insert into public.titles (id, title, type, synopsis, release_year, content_rating, runtime_minutes, seasons, episode_count, limited_series, cast_label, hero_position, is_featured, sort_order) values
  ('shawshank-redemption', 'The Shawshank Redemption', 'film', 'Sentenced to life for a crime he insists he did not commit, soft-spoken banker Andy Dufresne arrives at Shawshank State Penitentiary in 1947. Over two decades behind its walls, an unlikely friendship with fellow inmate Red becomes a lesson in patience, dignity, and stubborn hope.', 1994, 'R', 142, null, null, false, null, '30% 30%', false, 0),
  ('whiplash', 'Whiplash', 'film', 'Andrew, a first-year jazz drummer at an elite music conservatory, earns a seat in the studio band run by the brilliant and merciless Terence Fletcher. As rehearsal turns into obsession, Andrew has to decide how much of himself greatness is worth.', 2014, 'R', 107, null, null, false, null, '68% 30%', false, 1),
  ('moonlight', 'Moonlight', 'film', 'Told in three chapters, Moonlight follows Chiron from a bullied childhood in Miami through a turbulent adolescence and into a guarded adulthood, as he searches for a sense of self and the courage to let someone truly see him.', 2016, 'R', 112, null, null, false, null, '42% 30%', false, 2),
  ('past-lives', 'Past Lives', 'film', 'Nora and Hae Sung were inseparable as children in Seoul until her family emigrated. Twenty-four years later he visits her in New York, and over one quiet week the two old friends confront love, destiny, and the lives they did not get to live.', 2023, 'PG-13', 106, null, null, false, null, '20% 40%', false, 3),
  ('breaking-bad', 'Breaking Bad', 'series', 'When a mild-mannered Albuquerque chemistry teacher receives a terminal cancer diagnosis, he teams up with a former student to cook methamphetamine and secure his family’s future. Every choice pulls Walter White deeper into a criminal empire — and further from the man he used to be.', 2008, 'TV-MA', null, 5, 62, false, null, '75% 25%', true, 0),
  ('succession', 'Succession', 'series', 'Media titan Logan Roy controls one of the world’s largest entertainment conglomerates, and each of his four children wants a piece of it. As his health falters and his grip tightens, loyalty, ambition, and family become impossible to tell apart.', 2018, 'TV-MA', null, 4, 39, false, null, '50% 30%', false, 1),
  ('the-crown', 'The Crown', 'series', 'Crowned at twenty-five, Elizabeth II must weigh private life against the duties of the monarchy as Britain changes around her. Spanning decades of political upheaval and family strain, the series imagines the conversations behind palace doors.', 2016, 'TV-MA', null, 6, 60, false, null, '50% 40%', false, 2),
  ('normal-people', 'Normal People', 'series', 'In a small town in the west of Ireland, popular Connell and outsider Marianne begin a secret relationship in their final year of school. Through university in Dublin and beyond, they keep finding their way back to each other — even when they can’t say what they mean.', 2020, 'TV-MA', null, 1, 12, true, null, '62% 40%', false, 3),
  ('free-solo', 'Free Solo', 'documentary', 'Rock climber Alex Honnold prepares to scale the 3,000-foot granite face of El Capitan in Yosemite National Park — alone, with no rope and no protection. An intimate portrait of obsession, risk, and the people who love him while he chases an impossible goal.', 2018, 'PG-13', 100, null, null, false, 'Featuring', '28% 50%', false, 0),
  ('13th', '13th', 'documentary', 'Ava DuVernay examines the clause in the Thirteenth Amendment that ended slavery “except as a punishment for crime.” Scholars, activists, and politicians trace a direct line from emancipation to the modern era of mass incarceration in the United States.', 2016, 'TV-MA', 100, null, null, false, 'Featuring', '50% 40%', false, 1),
  ('my-octopus-teacher', 'My Octopus Teacher', 'documentary', 'Burned out and searching for meaning, filmmaker Craig Foster starts free-diving in a cold South African kelp forest, where he meets a curious young octopus. Over a year of daily visits, an extraordinary bond forms that changes how he sees the natural world — and himself.', 2020, 'TV-PG', 85, null, null, false, 'Featuring', '55% 40%', false, 2),
  ('wont-you-be-my-neighbor', 'Won’t You Be My Neighbor?', 'documentary', 'For more than three decades, Fred Rogers used a modest children’s television show to talk honestly about feelings, fear, and kindness. Through archival footage and interviews, this documentary explores the gentle radical behind Mister Rogers’ Neighborhood.', 2018, 'PG-13', 95, null, null, false, 'Featuring', '72% 30%', false, 3),
  ('the-godfather', 'The Godfather', 'film', 'When aging patriarch Vito Corleone is targeted by a rival family, his youngest son Michael — the one who swore to stay out of the family business — is drawn into a war that will decide who he becomes.', 1972, 'R', 175, null, null, false, null, '50% 30%', false, 4),
  ('schindlers-list', 'Schindler’s List', 'film', 'In occupied Poland, opportunistic businessman Oskar Schindler staffs his factory with Jewish workers for cheap labor — until the horror unfolding around him turns profit into a desperate effort to save as many lives as he can.', 1993, 'R', 195, null, null, false, null, '50% 30%', false, 5),
  ('manchester-by-the-sea', 'Manchester by the Sea', 'film', 'A withdrawn Boston handyman returns to his coastal hometown after his brother’s death and learns he has been named guardian of his teenage nephew — forcing him to face the past he left behind.', 2016, 'R', 138, null, null, false, null, '50% 35%', false, 6),
  ('marriage-story', 'Marriage Story', 'film', 'A theater director and an actor try to part ways gently, but a bicoastal divorce pulls in lawyers, pride, and their young son — testing how much love can survive the ending of a marriage.', 2019, 'R', 137, null, null, false, null, '50% 35%', false, 7),
  ('nomadland', 'Nomadland', 'film', 'After the economic collapse of her company town, a widow packs her life into a van and drives west, finding work, solitude, and an unexpected community among modern-day nomads.', 2021, 'R', 108, null, null, false, null, '50% 40%', false, 8),
  ('oppenheimer', 'Oppenheimer', 'film', 'The story of physicist J. Robert Oppenheimer, who led the secret wartime race to build the atomic bomb — and then lived with what his success had unleashed on the world.', 2023, 'R', 181, null, null, false, null, '50% 30%', false, 9),
  ('better-call-saul', 'Better Call Saul', 'series', 'Years before Breaking Bad, struggling lawyer Jimmy McGill hustles for clients in Albuquerque, and every shortcut he takes edges him closer to becoming the criminal attorney Saul Goodman.', 2015, 'TV-MA', null, 6, 63, false, null, '50% 30%', false, 4),
  ('mad-men', 'Mad Men', 'series', 'On Madison Avenue in the 1960s, brilliant ad man Don Draper sells dreams to America while guarding a carefully constructed identity — as the decade transforms everyone around him.', 2007, 'TV-14', null, 7, 92, false, null, '50% 30%', false, 5),
  ('chernobyl', 'Chernobyl', 'series', 'In April 1986, a reactor explodes at the Chernobyl nuclear plant. Scientists, officials, and ordinary workers race to contain the disaster while the Soviet state works just as hard to contain the truth.', 2019, 'TV-MA', null, 1, 5, true, null, '50% 35%', false, 6),
  ('the-sopranos', 'The Sopranos', 'series', 'New Jersey mob boss Tony Soprano starts seeing a psychiatrist after a series of panic attacks, and therapy becomes one more place where his two families — and his two selves — collide.', 1999, 'TV-MA', null, 6, 86, false, null, '50% 30%', false, 7),
  ('mare-of-easttown', 'Mare of Easttown', 'series', 'A small-town Pennsylvania detective, once a local basketball hero, investigates a young mother’s murder while her own life and family quietly fall apart around her.', 2021, 'TV-MA', null, 1, 7, true, null, '50% 35%', false, 8),
  ('the-queens-gambit', 'The Queen’s Gambit', 'series', 'Orphaned at nine, Beth Harmon learns chess from a janitor in a basement — and grows into a prodigy fighting her way to the top of a male-dominated game while battling her own dependencies.', 2020, 'TV-MA', null, 1, 7, true, null, '50% 30%', false, 9),
  ('man-on-wire', 'Man on Wire', 'documentary', 'In 1974, French high-wire artist Philippe Petit and a small band of friends sneak into the unfinished World Trade Center to string a cable between the Twin Towers — and attempt the impossible walk.', 2008, 'PG-13', 94, null, null, false, 'Featuring', '50% 40%', false, 4),
  ('searching-for-sugar-man', 'Searching for Sugar Man', 'documentary', 'A Detroit singer-songwriter vanished after two overlooked albums — unaware that he had become a legend in apartheid-era South Africa. Two fans set out to learn what really happened to him.', 2012, 'PG-13', 85, null, null, false, 'Featuring', '50% 40%', false, 5),
  ('jiro-dreams-of-sushi', 'Jiro Dreams of Sushi', 'documentary', 'Inside a ten-seat Tokyo restaurant, an 85-year-old sushi master pursues perfection one piece at a time, while his eldest son waits for the day he will inherit his father’s legacy.', 2011, 'PG', 82, null, null, false, 'Featuring', '50% 40%', false, 6),
  ('icarus', 'Icarus', 'documentary', 'A filmmaker sets out to test how easy it is to beat cycling’s doping controls, and his Russian adviser ends up at the center of an international scandal that reaches the highest levels of sport and state.', 2017, 'NR', 121, null, null, false, 'Featuring', '50% 40%', false, 7),
  ('senna', 'Senna', 'documentary', 'Told entirely through archival footage, the life of Brazilian Formula One champion Ayrton Senna — his fierce rivalry with Alain Prost, his faith, and his fight against the politics of the sport.', 2010, 'PG-13', 106, null, null, false, 'Featuring', '50% 40%', false, 8),
  ('american-factory', 'American Factory', 'documentary', 'When a Chinese billionaire reopens a shuttered General Motors plant in Ohio, hopeful local workers and transplanted Chinese staff collide over culture, pay, and what a good job is supposed to look like.', 2019, 'NR', 110, null, null, false, 'Featuring', '50% 40%', false, 9),
  ('12-angry-men', '12 Angry Men', 'film', 'On a sweltering afternoon, twelve jurors retreat to a cramped room to decide a teenager''s fate, and a quick guilty verdict seems certain. One quiet holdout asks the others to slow down. As tempers flare and assumptions crack, the deliberation becomes a tense study of doubt, prejudice and civic duty.', 1957, 'NR', 97, null, null, false, null, '50% 40%', false, 10),
  ('parasite', 'Parasite', 'film', 'A struggling family living in a cramped semi-basement apartment schemes its way, one member at a time, into jobs serving a wealthy household on the hill. The arrangement seems almost too good to last. Bong Joon Ho''s genre-bending satire turns a story about class into something sharp, funny and unnerving.', 2019, 'R', 133, null, null, false, null, '50% 35%', false, 11),
  ('the-pianist', 'The Pianist', 'film', 'When Nazi forces occupy Warsaw, a celebrated Jewish pianist watches his world shrink from concert halls to ghetto walls. Separated from his family, he survives through luck, hiding and the quiet help of strangers. A harrowing true story about endurance, loss and the music that keeps a person human.', 2002, 'R', 150, null, null, false, null, '50% 30%', false, 12),
  ('room', 'Room', 'film', 'Five-year-old Jack believes the single small room he shares with his mother is the entire world. For her, it is a prison she has spent years planning to escape. Told largely through a child''s eyes, this tender, gripping drama explores captivity, resilience and the overwhelming size of everything outside.', 2015, 'R', 118, null, null, false, null, '50% 35%', false, 13),
  ('lady-bird', 'Lady Bird', 'film', 'In early-2000s Sacramento, a headstrong Catholic-school senior who insists on being called Lady Bird dreams of escaping to an East Coast college. Her sharp-tongued, loving mother has other ideas. Greta Gerwig''s warm, funny coming-of-age story captures first loves, shifting friendships and the push-pull of family.', 2017, 'R', 94, null, null, false, null, '50% 30%', false, 14),
  ('the-social-network', 'The Social Network', 'film', 'A brilliant, socially awkward Harvard student builds a campus website that grows into a global phenomenon. Success brings lawsuits from former friends and rivals who say the idea was theirs. Through crackling dialogue and dueling depositions, the film examines ambition, loyalty and the price of building something enormous.', 2010, 'PG-13', 121, null, null, false, null, '50% 30%', false, 15),
  ('spotlight', 'Spotlight', 'film', 'A small team of Boston Globe investigative reporters begins digging into allegations against a single local priest. The more documents and survivors they find, the larger and more deliberate the pattern looks. A meticulous, quietly powerful portrait of journalism and the institutions that resist being held accountable.', 2015, 'R', 129, null, null, false, null, '50% 30%', false, 16),
  ('roma', 'Roma', 'film', 'In early-1970s Mexico City, Cleo works as a live-in housekeeper for a middle-class family whose household is quietly coming apart. As political unrest builds outside, her own life takes an unexpected turn. Shot in luminous black and white, Alfonso Cuarón''s intimate memory piece finds grandeur in everyday devotion.', 2018, 'R', 135, null, null, false, null, '50% 50%', false, 17),
  ('aftersun', 'Aftersun', 'film', 'An eleven-year-old girl spends a sunny holiday at a Turkish resort with her young, devoted father. Years later, she revisits their home-video footage and her own memories, searching for who he really was. A delicate, quietly devastating film about memory, parenthood and what we fail to see in the moment.', 2022, 'R', 101, null, null, false, null, '50% 45%', false, 18),
  ('boyhood', 'Boyhood', 'film', 'Filmed with the same cast over twelve years, this drama follows Mason from early childhood in Texas to his first day of college. Moves, stepfathers, first jobs and first heartbreaks unfold in small, ordinary moments. Richard Linklater''s experiment becomes a moving reflection on time and growing up.', 2014, 'R', 165, null, null, false, null, '50% 35%', false, 19),
  ('the-wire', 'The Wire', 'series', 'In Baltimore, a mismatched police detail sets out to bring down a powerful drug organization using wiretaps and patience. Each season widens the lens to the docks, city hall, schools and newsroom. Often called the greatest TV drama ever made, it is a sprawling portrait of an American city and its institutions.', 2002, 'TV-MA', null, 5, 60, false, null, '50% 35%', false, 10),
  ('six-feet-under', 'Six Feet Under', 'series', 'After a sudden death in the family, two estranged brothers inherit their father''s Los Angeles funeral home. Surrounded by grief every day, the Fishers struggle with their own relationships, secrets and fears. Darkly funny and deeply moving, this acclaimed drama treats mortality as the lens for understanding how to live.', 2001, 'TV-MA', null, 5, 63, false, null, '50% 30%', false, 11),
  ('friday-night-lights', 'Friday Night Lights', 'series', 'In the small town of Dillon, Texas, high school football is close to religion. A new head coach and his wife guide a team of teenagers carrying the hopes of an entire community. Shot with documentary-style intimacy, this beloved drama is really about family, class, faith and growing up.', 2006, 'TV-14', null, 5, 76, false, null, '50% 30%', false, 12),
  ('the-leftovers', 'The Leftovers', 'series', 'Three years after two percent of the world''s population inexplicably vanished, a small-town police chief tries to hold his fractured family and community together. Some cling to faith, others to strange new movements. This bold, emotionally raw series explores grief, belief and the search for meaning when answers never come.', 2014, 'TV-MA', null, 3, 28, false, null, '50% 30%', false, 13),
  ('band-of-brothers', 'Band of Brothers', 'series', 'Drawn from veterans'' recollections, this miniseries follows Easy Company of the 101st Airborne from paratrooper training through D-Day and the brutal final push into Germany. Each episode spotlights different soldiers as friendships are forged under fire. An epic, deeply respectful portrait of ordinary men in extraordinary circumstances.', 2001, 'TV-MA', null, 1, 10, true, null, '50% 35%', false, 14),
  ('the-americans', 'The Americans', 'series', 'In early-1980s Washington, D.C., a seemingly ordinary suburban couple are actually deep-cover Soviet spies raising two kids who know nothing. When an FBI agent moves in across the street, the pressure intensifies. A gripping Cold War thriller that is ultimately a profound study of marriage, loyalty and identity.', 2013, 'TV-MA', null, 6, 75, false, null, '50% 30%', false, 15),
  ('halt-and-catch-fire', 'Halt and Catch Fire', 'series', 'In the early 1980s, a charismatic salesman, a disillusioned engineer and a brilliant young coder team up to challenge the giants of the personal computer industry. Across a decade of booms and busts, their partnerships shift and evolve. A thoughtful drama about creativity, ambition and the people behind technological revolutions.', 2014, 'TV-14', null, 4, 40, false, null, '50% 30%', false, 16),
  ('downton-abbey', 'Downton Abbey', 'series', 'Beginning in 1912, the aristocratic Crawley family and their household staff navigate love, inheritance and duty on a grand English estate. As war, social change and modernity arrive, life upstairs and downstairs is transformed. A sweeping, elegant period drama filled with sharp wit and enduring characters.', 2010, 'TV-14', null, 6, 47, false, null, '50% 30%', false, 17),
  ('shogun', 'Shōgun', 'series', 'In feudal Japan in 1600, a shipwrecked English navigator becomes a pawn in the power struggle of a shrewd warlord surrounded by enemies. A gifted translator with a painful past bridges their worlds. Adapted from James Clavell''s novel, this lavish, record-setting epic is a gripping tale of politics, honor and survival.', 2024, 'TV-MA', null, 1, 10, false, null, '50% 30%', false, 18),
  ('the-night-of', 'The Night Of', 'series', 'A Pakistani-American college student borrows his father''s taxi for a night out in Manhattan and wakes up as the prime suspect in a brutal killing. A scrappy, eczema-plagued lawyer takes his case. This meticulous limited series examines the criminal justice system and how it changes everyone it touches.', 2016, 'TV-MA', null, 1, 8, true, null, '50% 35%', false, 19),
  ('hoop-dreams', 'Hoop Dreams', 'documentary', 'Two teenagers from Chicago''s inner city share one ambition: to play in the NBA. Following them across five years of high school, recruitment and family hardship, this landmark documentary reveals how race, money and opportunity shape the odds. An epic, deeply human portrait of hope under pressure.', 1994, 'PG-13', 174, null, null, false, 'Featuring', '50% 35%', false, 10),
  ('amy', 'Amy', 'documentary', 'Built almost entirely from archival footage, home videos and voice recordings, this documentary traces Amy Winehouse from a gifted North London teenager to a global star. It examines the pressures of fame, media scrutiny and addiction that surrounded her, while keeping her extraordinary voice and wit at the center.', 2015, 'R', 128, null, null, false, 'Featuring', '50% 30%', false, 11),
  ('three-identical-strangers', 'Three Identical Strangers', 'documentary', 'In 1980, a college freshman discovers he has a twin, and the media frenzy that follows reveals a third brother. Their joyful reunion makes them celebrities. But questions about why they were separated lead to unsettling discoveries. A twisty documentary about identity, nature versus nurture and institutional secrecy.', 2018, 'PG-13', 97, null, null, false, 'Featuring', '50% 30%', false, 12),
  ('blackfish', 'Blackfish', 'documentary', 'Centered on Tilikum, a captive orca involved in several deaths, this documentary examines what happens when intelligent, social animals are kept for entertainment. Former trainers, scientists and archival footage challenge the marine-park industry''s public image. A sobering investigation into animal welfare and corporate accountability.', 2013, 'PG-13', 83, null, null, false, 'Featuring', '50% 50%', false, 13),
  ('citizenfour', 'Citizenfour', 'documentary', 'A filmmaker receives encrypted messages from an anonymous source claiming evidence of vast government surveillance. She travels to a Hong Kong hotel room, where history unfolds in real time on camera. This tense, Oscar-winning documentary captures the moment Edward Snowden came forward and the questions about privacy that followed.', 2014, 'R', 113, null, null, false, 'Featuring', '50% 30%', false, 14),
  ('i-am-not-your-negro', 'I Am Not Your Negro', 'documentary', 'Drawing on an unfinished manuscript by James Baldwin about three slain civil rights leaders, this documentary weaves his words with archival footage and present-day images. Narrated by Samuel L. Jackson, it offers a searing, eloquent meditation on race in America that feels as urgent today as when written.', 2017, 'R', 93, null, null, false, 'Featuring', '50% 30%', false, 15),
  ('minding-the-gap', 'Minding the Gap', 'documentary', 'Three friends bonded by skateboarding in Rockford, Illinois, face the pressures of young adulthood across more than a decade of footage. As one becomes a father and another starts a job, the director turns the camera on their shared histories of difficult homes. An intimate, generous portrait of masculinity and growing up.', 2018, 'NR', 93, null, null, false, 'Featuring', '50% 40%', false, 16),
  ('honeyland', 'Honeyland', 'documentary', 'In a remote North Macedonian village, a woman keeps wild bees using an ancient rule: take half, leave half. When a large, noisy family moves in next door with plans of their own, the delicate balance is threatened. A visually stunning documentary about nature, sustainability and quiet resilience.', 2019, 'NR', 89, null, null, false, 'Featuring', '50% 40%', false, 17),
  ('grizzly-man', 'Grizzly Man', 'documentary', 'For thirteen summers, self-styled bear protector Timothy Treadwell lived among wild grizzlies in the Alaskan wilderness, filming himself and the animals he adored. Werner Herzog assembles that footage with interviews to explore Treadwell''s passion, his blind spots and the indifferent power of nature. Haunting, strange and unforgettable.', 2005, 'R', 103, null, null, false, 'Featuring', '50% 40%', false, 18),
  ('the-act-of-killing', 'The Act of Killing', 'documentary', 'Decades after Indonesia''s 1965 mass killings, men who took part are still celebrated in their communities. Invited to reenact their deeds in the style of their favorite movies, they stage elaborate scenes. What begins as boastful spectacle becomes a chilling, unprecedented look at memory, impunity and conscience.', 2012, 'NR', 159, null, null, false, 'Featuring', '50% 40%', false, 19)
on conflict (id) do update set title = excluded.title, type = excluded.type, synopsis = excluded.synopsis, release_year = excluded.release_year, content_rating = excluded.content_rating, runtime_minutes = excluded.runtime_minutes, seasons = excluded.seasons, episode_count = excluded.episode_count, limited_series = excluded.limited_series, cast_label = excluded.cast_label, hero_position = excluded.hero_position, is_featured = excluded.is_featured, sort_order = excluded.sort_order;

insert into public.genres (name) values ('Drama'), ('Crime'), ('Music'), ('Romance'), ('Comedy'), ('History'), ('Documentary'), ('Adventure'), ('Nature'), ('War'), ('Mystery'), ('Biography'), ('Sport') on conflict (name) do nothing;

